#include <stdlib.h>

typedef struct DNode {
    int val;
    struct DNode *prev, *next;
} DNode;

typedef struct { DNode *head, *tail; } DList;

DNode *dnode(int v) {
    DNode *n = malloc(sizeof *n);
    if (n) { n->val = v; n->prev = n->next = NULL; }
    return n;
}

void push_front(DList *l, int v) {
    DNode *n = dnode(v);
    if (!n) return;
    n->next = l->head;
    if (l->head) l->head->prev = n; else l->tail = n;
    l->head = n;
}

void push_back(DList *l, int v) {
    DNode *n = dnode(v);
    if (!n) return;
    n->prev = l->tail;
    if (l->tail) l->tail->next = n; else l->head = n;
    l->tail = n;
}

void unlink_node(DList *l, DNode *x) {
    if (x->prev) x->prev->next = x->next; else l->head = x->next;
    if (x->next) x->next->prev = x->prev; else l->tail = x->prev;
    free(x);
}

typedef struct LNode { struct LNode *prev, *next; } LNode;

static void l_init(LNode *h) { h->prev = h->next = h; }

static void l_insert_after(LNode *p, LNode *n) {
    n->prev = p;
    n->next = p->next;
    p->next->prev = n;
    p->next = n;
}
static void l_remove(LNode *x) {
    x->prev->next = x->next;
    x->next->prev = x->prev;
}
